//! IBI correction (inter-beat-interval cleaning): a 7-beat median and variance test on a
//! ring buffer, interpolation of rejected runs and, for the batch variant, resets at wear and
//! state changes. See `docs/algorithms/metrics.md`; the Python reference is
//! `tools/ibi_correction.py` and the vectors in the tests are generated by
//! `tools/gen_public_vectors_sleep.py`.
//!
//! Integer arithmetic throughout except the bpm tests, which use `f32` operations in a fixed
//! order (no fused multiply-add, no libm). Comparisons with NaN operands are defined (see
//! the predicates below).
//!
//! Ring buffer reads are bounds-checked and panic when out of range; `feed` never triggers this.

const RING_CAP: usize = 64;

/// One corrected event, as `feed` returns it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct IbiEvent {
    /// Corrected timestamp (the units of the input timestamps).
    pub ts: u64,
    /// Corrected IBI in milliseconds.
    pub ibi: u16,
    /// Corrected amplitude.
    pub amp: u16,
    /// Validity indicator: 0 first beat, 1 valid, 2 invalid, 3 interpolated.
    pub validity: u8,
}

/// Validity indicator values.
pub const VALID: u8 = 1;

#[derive(Clone, Copy, Default)]
struct Entry {
    ts0: u64,
    ts1: u64,
    ibi: u16,
    amp: u16,
    ibi_c: u16,
    amp_c: u16,
    ind: u8,
    flag: u8,
    vin: u8,
}

struct Ring {
    data: [Entry; RING_CAP],
    head: usize,
    tail: usize,
    full: bool,
}

impl Ring {
    fn new() -> Self {
        Ring {
            data: [Entry::default(); RING_CAP],
            head: 0,
            tail: 0,
            full: false,
        }
    }

    fn is_empty(&self) -> bool {
        !self.full && self.head == self.tail
    }

    fn count(&self) -> usize {
        if self.full {
            RING_CAP
        } else {
            (self.head + RING_CAP - self.tail) % RING_CAP
        }
    }

    fn push(&mut self, e: Entry) {
        self.data[self.head] = e;
        if self.full {
            self.tail = (self.tail + 1) % RING_CAP;
        }
        self.head = (self.head + 1) % RING_CAP;
        self.full = self.head == self.tail;
    }

    fn pop(&mut self) -> Option<Entry> {
        if self.is_empty() {
            return None;
        }
        let e = self.data[self.tail];
        self.full = false;
        self.tail = (self.tail + 1) % RING_CAP;
        Some(e)
    }

    /// Slot of the entry `idx` back from the head: 0 is the newest. `idx` is taken
    /// as its low byte, sign-extended.
    fn slot(&self, idx: i32) -> usize {
        assert!(!self.is_empty(), "ring read: empty ring");
        let i = idx as u8 as i8 as i32;
        assert!((i.unsigned_abs() as usize) < RING_CAP, "ring read: index");
        let j = i + RING_CAP as i32 + self.head as i32 - 1;
        assert!(j >= 0, "ring read: index");
        j as usize % RING_CAP
    }

    fn at(&self, idx: i32) -> &Entry {
        &self.data[self.slot(idx)]
    }

    fn at_mut(&mut self, idx: i32) -> &mut Entry {
        let s = self.slot(idx);
        &mut self.data[s]
    }
}

// --- float comparisons ---------------------------------------------------------------
// A comparison with a NaN operand is false, so `not_greater` and `not_less` are true for NaN.

fn greater(a: f32, b: f32) -> bool {
    a > b
}
fn not_greater(a: f32, b: f32) -> bool {
    !(a > b)
}
fn at_most(a: f32, b: f32) -> bool {
    a <= b
}
fn less(a: f32, b: f32) -> bool {
    a < b
}
fn not_less(a: f32, b: f32) -> bool {
    !(a < b)
}

fn bpm(ibi: u16) -> f32 {
    60000.0f32 / ibi as f32
}

/// bpm variance of the 7 window IBIs; a zero IBI counts as bpm 0.
fn variance_window(a: &[u16; 7]) -> f32 {
    let b: Vec<f32> = a.iter().map(|&x| if x != 0 { bpm(x) } else { 0.0 }).collect();
    let mut s = b[0];
    for &x in &b[1..] {
        if x != 0.0 {
            s += x;
        }
    }
    let mean = s / 7.0;
    let mut acc = 0.0f32;
    for (k, &x) in b.iter().enumerate() {
        let d = x - mean;
        let t = d * d;
        acc = if k == 0 { t } else { acc + t };
    }
    acc / 6.0
}

/// the same over ring entries -6..0, without the zero guard.
fn variance_ring(r: &Ring) -> f32 {
    let b: Vec<f32> = (-6..=0).map(|i| bpm(r.at(i).ibi)).collect();
    let mut s = b[0];
    for &x in &b[1..] {
        s += x;
    }
    let mean = s / 7.0;
    let mut acc = 0.0f32;
    for (k, &x) in b.iter().enumerate() {
        let d = x - mean;
        let t = d * d;
        acc = if k == 0 { t } else { acc + t };
    }
    acc / 6.0
}

fn median7<T: Ord + Copy>(mut v: [T; 7]) -> T {
    v.sort();
    v[3]
}

/// State of the IBI corrector.
pub struct IbiCorrection {
    buf0: Ring,
    buf1: Ring,
    count: i32,
    max_out: u16,
    gap_ms: u16,
    prev_ibi: u16,
    flag_a: bool,
    flag_b: bool,
    prev_bpm: f32,
    max_bpm: f32,
    rej: u8,
    rej2: u8,
    a: [u16; 7],
    c: [u16; 7],
    d: [u32; 7],
    f: [u64; 7],
    g: [u8; 7],
    me_f0: f32,
    me_flag: bool,
    me_prev_ibi: u16,
    ts: u64,
    ts_epoch: bool,
    out: Vec<IbiEvent>,
}

impl Default for IbiCorrection {
    fn default() -> Self {
        Self::new()
    }
}

impl IbiCorrection {
    /// Defaults: 4 events per call, interpolation limit 5000, `flag_a`
    /// off, `flag_b` on, 150 bpm ceiling.
    pub fn new() -> Self {
        Self::with_params(4, 5000, false, true, 150.0)
    }

    /// Explicit parameters.
    pub fn with_params(max_out: u16, gap_ms: u16, flag_a: bool, flag_b: bool, max_bpm: f32) -> Self {
        IbiCorrection {
            buf0: Ring::new(),
            buf1: Ring::new(),
            count: 0,
            max_out,
            gap_ms,
            prev_ibi: 1000,
            flag_a,
            flag_b,
            prev_bpm: 60.0,
            max_bpm,
            rej: 0,
            rej2: 0,
            a: [0; 7],
            c: [0; 7],
            d: [0; 7],
            f: [0; 7],
            g: [0; 7],
            me_f0: 0.0,
            me_flag: flag_b,
            me_prev_ibi: 1000,
            ts: 0,
            ts_epoch: true,
            out: Vec::new(),
        }
    }

    /// Feed one beat; returns the events emitted during this call (up to `max_out`, three beats behind the input).
    pub fn feed(&mut self, ts: u64, ibi: u16, amp: u16) -> Vec<IbiEvent> {
        self.feed_with_validity(ts, ibi, amp, 0)
    }

    /// As `feed`, with an input validity byte (`feed` passes 0). A byte of 7 or more makes the beat invalid when `flag_b` is off.
    pub fn feed_with_validity(&mut self, ts: u64, ibi: u16, amp: u16, vin: u8) -> Vec<IbiEvent> {
        self.ts = ts;
        self.out = Vec::new();
        self.run(ibi, amp, vin);
        std::mem::take(&mut self.out)
    }

    fn run(&mut self, ibi: u16, amp: u16, vin: u8) {
        if ibi != 0 {
            self.count = self.count.wrapping_add(1);
            let mut e = Entry {
                ts0: self.ts,
                ibi,
                amp,
                flag: 1,
                vin,
                ..Entry::default()
            };
            self.buf0.push(e);
            if self.count == 1 {
                e.ts1 = self.ts;
                e.ibi_c = ibi;
                e.amp_c = amp;
                e.ind = 0;
                if self.ts.wrapping_sub(1) <= 99_999_999_998 {
                    self.ts_epoch = false;
                }
                self.buf1.push(e);
            } else if self.count >= 5 {
                self.classify();
            }
        }
        self.drain();
    }

    fn classify(&mut self) {
        let (ibx, xvin) = {
            let x = self.buf0.at(-3);
            (x.ibi, x.vin)
        };
        let bpm_cur = if ibx != 0 { bpm(ibx) } else { 60000.0 };
        let n = self.buf0.count();
        let mx = self.max_bpm;
        let prev = self.prev_bpm;
        let p = self.prev_ibi as u32;
        let ibi_jump = |ibx: u16| (ibx as i32 - p as i32).unsigned_abs() * 100 > (p * 5) << 2;
        let reject;
        if n <= 6 {
            reject = if self.flag_b {
                at_most(bpm_cur, 30.0)
                    || greater(bpm_cur, mx)
                    || less(bpm_cur, prev * 0.625)
                    || greater(bpm_cur, prev + 18.0)
                    || !not_less(bpm_cur, prev + -25.0)
            } else {
                at_most(bpm_cur, 30.0) || greater(bpm_cur, mx) || ibi_jump(ibx) || xvin >= 7
            };
            if reject {
                self.buf0.at_mut(-3).flag = 0;
                self.rej = self.rej.wrapping_add(1);
                self.prev_bpm = bpm_cur;
                self.prev_ibi = ibx;
            } else {
                self.accept(bpm_cur, ibx);
            }
        } else {
            let mut w = [0u16; 7];
            for (k, i) in (-6..=0).enumerate() {
                w[k] = self.buf0.at(i).ibi;
            }
            let m = median7(w);
            let bpm_med = bpm(if m & 0xFFFE != 0 { m } else { 1 });
            let tot: u32 = w.iter().map(|&x| x as u32).sum();
            let mean_ibi = tot as f32 / 7.0;
            let bpm_mean = 60000.0f32 / mean_ibi;
            let bpm_diff = (if mean_ibi != 0.0 { bpm_mean } else { 0.0 }) - bpm_cur;
            let sq = bpm_diff * bpm_diff;
            reject = if self.flag_b {
                at_most(bpm_cur, 30.0)
                    || greater(bpm_cur, mx)
                    || greater((bpm_cur - bpm_med).abs(), 14.0)
                    || less(bpm_cur, prev * 0.625)
                    || greater(bpm_cur, prev + 23.0)
                    || less(bpm_cur, prev + -16.0)
                    || greater(sq, variance_ring(&self.buf0) * 1.5)
            } else {
                at_most(bpm_cur, 30.0)
                    || greater(bpm_cur, mx)
                    || greater((bpm_cur - bpm_med).abs(), 14.0)
                    || ibi_jump(ibx)
                    || greater(sq, variance_ring(&self.buf0) * 1.5)
                    || xvin >= 7
            };
            if reject {
                self.buf0.at_mut(-3).flag = 0;
                self.rej = self.rej.wrapping_add(1);
                if self.rej >= 4 {
                    // the first three rejections leave the reference bpm alone
                    self.prev_bpm = bpm_cur;
                    self.prev_ibi = ibx;
                }
            } else {
                self.accept(bpm_cur, ibx);
            }
        }
        self.tail();
    }

    fn accept(&mut self, bpm_cur: f32, ibx: u16) {
        self.buf0.at_mut(-3).flag = 1;
        self.rej2 = self.rej;
        self.rej = 0;
        self.prev_bpm = bpm_cur;
        self.prev_ibi = ibx;
    }

    /// after the beat at -3 is classified.
    fn tail(&mut self) {
        if self.buf0.at(-3).flag == 1 && self.buf0.at(-4).flag == 0 {
            self.gap();
        } else {
            self.after(0);
        }
    }

    /// the beat at -3 is good and the one before it is not. Find the previous
    /// good beat and fix up the run in between.
    fn gap(&mut self) {
        let mut skip: i32 = 0;
        let prev_good = loop {
            let prev_good = skip - 4;
            if self.buf0.at(prev_good).flag != 0 {
                break prev_good;
            }
            let next_back = skip - 5;
            skip -= 1;
            if next_back <= -64 {
                if self.rej > 0x3C {
                    return self.flush(0xC1, self.rej as u32, true);
                }
                return self.flush_pending_rejects();
            }
        };
        let run_start = skip - 3;
        let (prev_ibi_v, ts_prev) = {
            let e = self.buf0.at(prev_good);
            (e.ibi as i32, e.ts0)
        };
        let (cur_ibi_v, ts_cur) = {
            let e = self.buf0.at(-3);
            (e.ibi as i32, e.ts0)
        };
        let mut sum_rej: i32 = 0;
        if prev_good <= -5 {
            for i in run_start..-3 {
                sum_rej += self.buf0.at(i).ibi as i32;
            }
        }
        let ibi_sum = (cur_ibi_v + prev_ibi_v) as u32;
        let n_est = ((sum_rej as f32 / (ibi_sum >> 1) as f32).round() as i32).max(1);
        let eq = n_est.wrapping_add(skip) == 0;
        if sum_rej > self.gap_ms as i32 || 1 - skip > self.max_out as i32 {
            return self.too_long(run_start, prev_good);
        }
        self.interpolate(Gap {
            cur_ibi: cur_ibi_v,
            prev_ibi: prev_ibi_v,
            skip,
            prev_good,
            run_start,
            sum_rejected: sum_rej,
            ibi_sum,
            n_est,
            eq,
            ts_prev,
            ts_cur,
        });
    }

    /// too many rejected beats to interpolate; emit them as invalid (2).
    fn too_long(&mut self, mut run_start: i32, prev_good: i32) {
        let ts_last;
        if self.buf0.at(run_start).flag != 0 {
            ts_last = 0;
        } else {
            let mut last;
            loop {
                let e = *self.buf0.at(run_start);
                let mut l = e;
                l.amp_c = 0;
                l.ind = 2;
                l.ibi_c = e.ibi;
                l.ts1 = e.ts0;
                self.buf1.push(l);
                run_start += 1;
                last = e.ts0;
                if self.buf0.at(run_start).flag != 0 {
                    break;
                }
            }
            ts_last = last;
        }
        if self.gap_ms != 0 {
            let m = Entry {
                ts1: ts_last,
                ind: 2,
                ..Entry::default()
            };
            self.buf1.push(m);
        }
        self.after(prev_good);
    }

    /// replace the rejected run by `n_est` interpolated beats (validity 3).
    fn interpolate(&mut self, g: Gap) {
        let neg_skip = -g.skip;
        let end_idx = g.n_est.wrapping_add(g.skip).wrapping_sub(4);
        let ts_epoch = self.ts_epoch;
        let mut last_ts: u64 = 0;
        let mut sum_interp: i32 = 0;
        let step = ((g.cur_ibi - g.prev_ibi) as f32 / g.n_est.wrapping_add(1) as f32).round() as i32;
        let mut pos = g.prev_good;
        let mut cur_val = step.wrapping_add(g.prev_ibi);
        loop {
            let idx = pos + 1;
            let e = *self.buf0.at(idx);
            let mut l;
            if neg_skip >= g.n_est || idx < -3 {
                l = e;
                last_ts = e.ts0;
            } else {
                l = Entry::default();
                l.ts0 = last_ts;
            }
            l.ibi_c = cur_val as u16;
            l.amp_c = 0;
            l.ind = 3;
            self.buf1.push(l);
            pos += 1;
            sum_interp = sum_interp.wrapping_add(cur_val);
            cur_val = cur_val.wrapping_add(step);
            if pos >= end_idx {
                break;
            }
        }
        if self.flag_a && g.ibi_sum >= 2 {
            return self.amp_check(g.eq, end_idx, g.n_est, g.prev_good, g.run_start);
        }
        // remainder distribution
        let resid = g.sum_rejected.wrapping_sub(sum_interp);
        let q = (resid as f32 / g.n_est as f32).trunc() as i32;
        let ts_div = if ts_epoch { 1.0f32 } else { 1000.0f32 };
        let mut rem = resid.wrapping_sub(g.n_est.wrapping_mul(q));
        let mut out_idx = 1i32.wrapping_sub(g.n_est);
        let mut keep_ok = g.eq;
        let mut cnt = g.prev_good;
        let mut acc: u64 = 0;
        loop {
            let ref_ibi = self.buf0.at(end_idx).ibi as i32;
            let e2 = self.buf1.at_mut(out_idx);
            let v: i32 = if rem == 0 {
                e2.ibi_c as i32 + q
            } else if rem > 0 {
                rem -= 1;
                q + 1 + e2.ibi_c as i32
            } else {
                rem += 1;
                q - 1 + e2.ibi_c as i32
            };
            e2.ibi_c = v as u16;
            acc += (v as u16) as u64;
            let ts = ((acc as f32 / ts_div).round() as i64 as u64).wrapping_add(g.ts_prev);
            e2.ts1 = if ts > g.ts_cur { g.ts_cur } else { ts };
            keep_ok = keep_ok && (ref_ibi - e2.ibi_c as i32).abs() < 0x7E;
            cnt += 1;
            out_idx += 1;
            if cnt >= end_idx {
                break;
            }
        }
        self.amp_check(keep_ok, end_idx, g.n_est, g.prev_good, g.run_start);
    }

    /// with the amplitude flag or an equal-count run, copy the real IBIs into
    /// the interpolated slots and decide whether the run is valid (1) or not (2).
    fn amp_check(&mut self, ok: bool, end_idx: i32, n_est: i32, prev_good: i32, run_start: i32) {
        if !ok {
            return self.after(prev_good);
        }
        let mut out_idx = 1i32.wrapping_sub(n_est);
        let mut src_idx = prev_good;
        let mut dst_idx = out_idx;
        loop {
            src_idx += 1;
            let ibi = self.buf0.at(src_idx).ibi;
            self.buf1.at_mut(dst_idx).ibi_c = ibi;
            dst_idx += 1;
            if src_idx >= end_idx {
                break;
            }
        }
        let cur_ibi_v = self.buf0.at(-3).ibi;
        let prev_good_ibi = self.buf0.at(prev_good).ibi;
        let bpm_lo = bpm(cur_ibi_v.min(prev_good_ibi)) + 34.5;
        let mut mn: u16 = 0xFFFF;
        let mut mxr: u16 = 0;
        if run_start <= -4 {
            for i in run_start..-3 {
                let v = self.buf0.at(i).ibi;
                if mn >= v {
                    mn = v;
                }
                if mxr < v {
                    mxr = v;
                }
            }
        }
        let bpm_min = bpm(mn);
        let (keep, ind);
        if not_less(bpm_min, bpm_lo) {
            keep = false;
            ind = 2;
        } else {
            let mut bpm_hi = bpm(cur_ibi_v.max(prev_good_ibi)) + -24.0;
            let bpm_max = bpm(mxr);
            let bpm_cap = f32::from_bits(0x41F0CCCD);
            if less(bpm_hi, bpm_cap) {
                bpm_hi = bpm_cap;
            }
            if not_greater(bpm_max, bpm_hi) {
                keep = false;
                ind = 2;
            } else {
                keep = true;
                ind = 1;
            }
        }
        src_idx = prev_good;
        loop {
            let e = self.buf1.at_mut(out_idx);
            e.ind = ind;
            if keep {
                e.amp_c = e.amp;
                e.ts1 = e.ts0;
            }
            src_idx += 1;
            out_idx += 1;
            if src_idx >= end_idx {
                break;
            }
        }
        self.after(prev_good);
    }

    /// too many rejected beats pile up, flush them as invalid (2).
    fn after(&mut self, prev_good: i32) {
        if self.rej > 0x3C {
            return self.flush(0xC1, self.rej as u32, true);
        }
        if prev_good > -0x40 {
            return self.finish();
        }
        self.flush_pending_rejects();
    }

    fn flush_pending_rejects(&mut self) {
        let n_rej = self.rej2 as u32;
        if n_rej == 0 {
            return self.finish();
        }
        self.flush(-3 - n_rej as i32, n_rej, false);
    }

    fn flush(&mut self, mut idx: i32, mut remaining: u32, dec: bool) {
        loop {
            let e = *self.buf0.at(idx);
            let mut l = e;
            l.amp_c = 0;
            l.ind = 2;
            l.ibi_c = e.ibi;
            l.ts1 = e.ts0;
            self.buf1.push(l);
            let m = self.buf0.at_mut(idx);
            m.ibi = 0;
            m.amp = 0;
            m.ind = 0;
            self.buf0.pop();
            if dec {
                self.rej = self.rej.wrapping_sub(1);
            }
            remaining = remaining.wrapping_sub(1);
            idx += 1;
            if remaining & 0xFF == 0 {
                break;
            }
        }
        self.finish();
    }

    fn finish(&mut self) {
        let cur = *self.buf0.at(-3);
        if cur.flag == 1 {
            let mut l = cur;
            l.ibi_c = cur.ibi;
            l.amp_c = cur.amp;
            l.ind = 1;
            l.ts1 = cur.ts0;
            self.buf1.push(l);
        }
    }

    /// Output stage: up to `max_out` events, each the centre of a 7-beat window.
    fn drain(&mut self) {
        if self.buf1.is_empty() {
            return;
        }
        let mut n: u16 = 0;
        loop {
            if n >= self.max_out {
                return;
            }
            let e = self.buf1.pop().expect("non-empty ring");
            if e.ibi_c != 0 && self.count >= 0 {
                self.a.rotate_left(1);
                self.a[6] = e.ibi_c;
                self.c.rotate_left(1);
                self.c[6] = e.amp_c;
                self.d.rotate_left(1);
                self.d[6] = e.ind as u32;
                self.f.rotate_left(1);
                self.f[6] = e.ts1;
                self.g.rotate_left(1);
                self.g[6] = e.vin;
                if self.a[0] != 0 {
                    self.median_error();
                }
                if self.a[3] != 0 {
                    self.out.push(IbiEvent {
                        ts: self.f[3],
                        ibi: self.a[3],
                        amp: self.c[3],
                        validity: self.d[3] as u8,
                    });
                    n += 1;
                }
            }
            if self.buf1.is_empty() {
                return;
            }
        }
    }

    /// Demote the centre beat (indicator 1 to 2) when it departs from
    /// the 7-beat median and mean.
    fn median_error(&mut self) {
        if self.d[3] != 1 {
            return;
        }
        let a = self.a;
        let ibi_c = a[3];
        let bpm_c = bpm(ibi_c);
        if self.me_f0 == 0.0 {
            self.me_f0 = bpm_c;
        }
        let signed = a.map(|x| x as i16);
        let med = median7(signed);
        let sum: i32 = signed.iter().map(|&x| x as i32).sum();
        let mean = sum as f32 / 7.0;
        let bpm_med = 60000.0f32 / med as f32;
        let bpm_mean = 60000.0f32 / ((mean as i32) as f32);
        let f0 = self.me_f0;
        let mx = self.max_bpm;
        let p = self.me_prev_ibi as u32;
        let d = bpm_mean - bpm_c;
        let sq = d * d;
        let fail = if self.me_flag {
            at_most(bpm_c, 30.0)
                || greater(bpm_c, mx)
                || greater((bpm_c - bpm_med).abs(), 18.0)
                || greater(bpm_c, f0 + 23.0 + 4.0)
                || less(bpm_c, f0 * 0.625)
                || less(bpm_c, f0 + -16.0 + -4.0)
                || greater(sq, variance_window(&a) * 5.0)
        } else {
            at_most(bpm_c, 30.0)
                || greater(bpm_c, mx)
                || greater((bpm_c - bpm_med).abs(), 18.0)
                || (ibi_c as i32 - p as i32).unsigned_abs() * 100 > p * 25
                || greater(sq, variance_window(&a) * 5.0)
                || self.g[3] >= 7
        };
        if fail {
            self.d[3] = 2;
        }
        self.me_f0 = bpm_c;
        self.me_prev_ibi = ibi_c;
    }
}

struct Gap {
    cur_ibi: i32,
    prev_ibi: i32,
    skip: i32,
    prev_good: i32,
    run_start: i32,
    sum_rejected: i32,
    ibi_sum: u32,
    n_est: i32,
    eq: bool,
    ts_prev: u64,
    ts_cur: u64,
}

/// Run a night through one freshly initialized state. `beats` are `(timestamp, ibi_ms, amplitude)`.
pub fn correct_ibis(beats: &[(u64, u16, u16)]) -> Vec<IbiEvent> {
    let mut c = IbiCorrection::new();
    let mut out = Vec::new();
    for &(ts, ibi, amp) in beats {
        out.extend(c.feed(ts, ibi, amp));
    }
    out
}

/// Merge two `(timestamp, state)` lists by timestamp; on equal
/// timestamps the entry of the second list goes first.
pub fn merge_data(a: (&[u64], &[u8]), b: (&[u64], &[u8])) -> (Vec<u64>, Vec<u8>) {
    let (mut ts, mut st) = (Vec::new(), Vec::new());
    let (mut i, mut j) = (0, 0);
    while i < a.0.len() && j < b.0.len() {
        if a.0[i] < b.0[j] {
            ts.push(a.0[i]);
            st.push(a.1[i]);
            i += 1;
        } else {
            ts.push(b.0[j]);
            st.push(b.1[j]);
            j += 1;
        }
    }
    ts.extend_from_slice(&a.0[i..]);
    st.extend_from_slice(&a.1[i..]);
    ts.extend_from_slice(&b.0[j..]);
    st.extend_from_slice(&b.1[j..]);
    (ts, st)
}

/// The first state-change timestamp above `after`
/// that is not a 5/6 or 6/5 transition (index 0 never counts); `u64::MAX` if none.
pub fn next_reset_timestamp(after: u64, ts: &[u64], st: &[u8]) -> u64 {
    for i in 1..ts.len() {
        if ts[i] <= after {
            continue;
        }
        if matches!((st[i - 1], st[i]), (6, 5) | (5, 6)) {
            continue;
        }
        return ts[i];
    }
    u64::MAX
}

/// The batch variant. A fresh state is used for each run
/// of beats; the state (and its undelivered beats) is dropped when a beat's timestamp
/// passes the next reset timestamp, which comes from the merged state-change and wear
/// lists. At most one reset per beat.
pub fn correct_stateless(
    ts: &[u64],
    ibi: &[u16],
    amp: &[u16],
    state_changes: (&[u64], &[u8]),
    wear: (&[u64], &[u8]),
) -> Vec<IbiEvent> {
    let (m_ts, m_st) = merge_data(state_changes, wear);
    let mut reset = next_reset_timestamp(0, &m_ts, &m_st);
    let mut c = IbiCorrection::new();
    let mut out = Vec::new();
    for k in 0..ts.len().min(ibi.len()).min(amp.len()) {
        if ts[k] > reset {
            c = IbiCorrection::new();
            reset = next_reset_timestamp(reset, &m_ts, &m_st);
        }
        out.extend(c.feed(ts[k], ibi[k], amp[k]));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    fn events_hash(ev: &[IbiEvent]) -> u64 {
        let mut h: u64 = 0xCBF29CE484222325;
        for e in ev {
            let mut bytes = Vec::with_capacity(13);
            bytes.extend_from_slice(&e.ts.to_le_bytes());
            bytes.extend_from_slice(&e.ibi.to_le_bytes());
            bytes.extend_from_slice(&e.amp.to_le_bytes());
            bytes.push(e.validity);
            for b in bytes {
                h = (h ^ b as u64).wrapping_mul(0x100000001B3);
            }
        }
        h
    }

    macro_rules! vector_tests {
        () => {
        fn check(name: &str, i: usize, got: &[IbiEvent], v: &Vector) {
            assert_eq!(got.len(), v.n_events, "{name} {i}: event count");
            for (k, want) in v.first_events.iter().enumerate() {
                let g = &got[k];
                assert_eq!((g.ts, g.ibi, g.amp, g.validity), *want, "{name} {i}: event {k}");
            }
            assert_eq!(events_hash(got), v.events_hash, "{name} {i}: events");
        }

        #[test]
        fn matches_reference_stateful() {
            for (i, v) in VECTORS.iter().enumerate() {
                let (max_out, gap_ms, flag_a, flag_b, max_bpm) = v.params;
                let mut c = IbiCorrection::with_params(max_out, gap_ms, flag_a, flag_b, max_bpm);
                let mut got = Vec::new();
                for &(ts, ibi, amp, vin) in v.beats {
                    got.extend(c.feed_with_validity(ts, ibi, amp, vin));
                }
                check("stateful", i, &got, v);
            }
        }

        #[test]
        fn matches_reference_stateless() {
            for (i, v) in STATELESS_VECTORS.iter().enumerate() {
                let ts: Vec<u64> = v.vector.beats.iter().map(|b| b.0).collect();
                let ibi: Vec<u16> = v.vector.beats.iter().map(|b| b.1).collect();
                let amp: Vec<u16> = v.vector.beats.iter().map(|b| b.2).collect();
                let got = correct_stateless(
                    &ts,
                    &ibi,
                    &amp,
                    (v.state_change_ts, v.state_change_states),
                    (v.wear_ts, v.wear_states),
                );
                check("stateless", i, &got, &v.vector);
            }
        }
        };
    }

    mod python_port {
        use super::*;
        include!("vectors/ibi_correction.rs");
        vector_tests!();
    }


    #[test]
    fn merge_and_reset() {
        let (ts, st) = merge_data((&[10, 30], &[1, 2]), (&[10, 20], &[3, 4]));
        assert_eq!((ts, st), (vec![10, 10, 20, 30], vec![3, 1, 4, 2]));
        assert_eq!(next_reset_timestamp(0, &[5, 6, 7], &[6, 5, 1]), 7);
        assert_eq!(next_reset_timestamp(0, &[5], &[1]), u64::MAX);
    }

    #[test]
    fn short_inputs() {
        let mut c = IbiCorrection::new();
        assert!(c.feed(1_700_000_000_000, 0, 5).is_empty());
        // nothing is emitted before the fifth beat: the first four only fill the rings
        for k in 1..=4u64 {
            assert!(c.feed(1_700_000_000_000 + 800 * k, 800, 5).is_empty());
        }
    }
}
